pragma solidity 0.8.38;

import {
    IAccessControlDefaultAdminRules
} from "@openzeppelin/contracts/access/extensions/IAccessControlDefaultAdminRules.sol";
import {IERC5267} from "@openzeppelin/contracts/interfaces/IERC5267.sol";

import {IManicFlashOptionAdmin} from "./IManicFlashOptionAdmin.sol";
import {IManicFlashOptionErrors} from "./IManicFlashOptionErrors.sol";
import {IManicFlashOptionEvents} from "./IManicFlashOptionEvents.sol";
import {IManicFlashOptionPool} from "./IManicFlashOptionPool.sol";
import {IManicFlashOptionRoles} from "./IManicFlashOptionRoles.sol";
import {IManicFlashOptionSettlement} from "./IManicFlashOptionSettlement.sol";
import {IManicFlashOptionTrading} from "./IManicFlashOptionTrading.sol";
import {IManicFlashOptionViews} from "./IManicFlashOptionViews.sol";

/// @title IManicFlashOption
/// @author Manic
/// @notice The contract's ABI, the one the backend and the frontend build against. It is committed as
///         `abi/IManicFlashOption.json`, and CI fails if that file is out of date.
/// @dev An aggregate: it declares nothing itself (docs/CONVENTIONS.md §6). It holds our function slices, one per
///      module, every event, every error and the role ids, plus OpenZeppelin's role management
///      (`IAccessControlDefaultAdminRules`) and EIP-712 domain (`IERC5267`) interfaces. The upgrade functions
///      (`upgradeToAndCall`, `proxiableUUID`) are only in the implementation's own ABI, because only deploy and
///      upgrade scripts call them.
///
///      The order of the parents matters (docs/ARCHITECTURE.md §3.2). Our interfaces come first (the slices, then the
///      events, errors and roles), then OpenZeppelin's. `ManicFlashOption`, `FlashOptionBase` and every module list
///      them in that same order. Otherwise the compiler can't linearize the inheritance graph.
/// @custom:security-contact See SECURITY.md
interface IManicFlashOption is
    IManicFlashOptionAdmin,
    IManicFlashOptionTrading,
    IManicFlashOptionSettlement,
    IManicFlashOptionPool,
    IManicFlashOptionViews,
    IManicFlashOptionEvents,
    IManicFlashOptionErrors,
    IManicFlashOptionRoles,
    IAccessControlDefaultAdminRules,
    IERC5267
{}

src/interfaces/IManicFlashOptionAdmin.so.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.38;

import {ConfigParams, InitParams} from "../types/ParamTypes.sol";

/// @title IManicFlashOptionAdmin
/// @author Manic
/// @notice The contract's setup and admin functions (docs/ARCHITECTURE.md §8.1, §8.9b). None of them moves money.
///         The ones that could redirect it (market creation, the floor, the recipients) need the admin, which is the
///         48-hour timelock on mainnet.
/// @dev Access control comes first in every function, then its checks in the order listed. `initialize` is
///      implemented by `ManicFlashOption`, the rest by `AdminModule`.
/// @custom:security-contact See SECURITY.md
interface IManicFlashOptionAdmin {
    /// @notice Sets the proxy up: grants every role and sets the token, the pool floor, the fee and rewards
    ///         recipients, the safety refund delay and the circuit breaker. It runs once, inside the transaction that
    ///         deploys the proxy, so nobody can call it first.
    /// @dev Emits OpenZeppelin's {RoleGranted} for each role holder, then {PoolFloorUpdated}, {RecipientsUpdated},
    ///      {RefundDelayUpdated} and {CircuitBreakerUpdated}, then OpenZeppelin's {Initialized}. These are the events
    ///      the matching admin setters emit, so an indexer sees the initial settings the same way as later changes.
    ///
    /// Requirements (in check order):
    /// - Called once, through the proxy. Never on the implementation (`InvalidInitialization`).
    /// - Every address is non-zero (`ZeroAddress`), checked in field order: admin, upgrader, operator, guardian, each
    ///   opener, each settler, token, fee recipient, rewards recipient.
    /// - The token has 6 to 9 decimals, so every amount fits a `uint64` (`InvalidTokenDecimals`).
    /// - The pool floor is at least 500 whole tokens (`InvalidLeverageParams`).
    /// - The refund delay is 0, meaning off, or at least 1 hour (`InvalidRefundDelay`).
    /// - The circuit breaker's window is 60 to 86,400 seconds (`InvalidBreakerParams`).
    ///
    /// @param p Every setting, in one struct (src/types/ParamTypes.sol).
    function initialize(InitParams calldata p) external;

    /// @notice Creates a market for a price feed at one leverage, switched off. One feed can have a market per
    ///         leverage (BTC at 1000x, 500x and 100x), each with its own settings (ADR 0008). The operator switches it
    ///         on with `setConfig` once its settings are checked.
    /// @dev The market is stored at the next index with its leverage and every setting of `p`, unpaused. The pair
    ///      (`marketId`, `leverage`) is its key, so neither ever changes. It is always created switched off, so
    ///      `p.enabled` must be false. Emits {MarketCreated}, then {ConfigUpdated} with the settings as stored.
    ///
    /// Requirements (in check order):
    /// - The caller holds `DEFAULT_ADMIN_ROLE` (`AccessControlUnauthorizedAccount`).
    /// - `marketId` is not zero (`InvalidLeverageParams`).
    /// - No market has this feed and leverage yet (`MarketExists`).
    /// - `priceExponent` is -18 to 0 (`InvalidLeverageParams`).
    /// - `p.enabled` is false (`InvalidLeverageParams`).
    /// - The leverage is 1x to 10,000x, and the settings pass `ConfigLib.validate` at it (`InvalidLeverageParams`).
    /// - Fewer than 65,535 markets exist (`MathOverflow`).
    ///
    /// @param marketId The price feed's Pyth id.
    /// @param leverage The market's leverage, 1x to 10,000x (1000 is 1000x). With `marketId`, it identifies the market
    ///        from now on.
    /// @param priceExponent The feed's price exponent (BTC: -8), fixed for the market's life.
    /// @param p The market's settings.
    function createMarket(bytes32 marketId, uint16 leverage, int8 priceExponent, ConfigParams calldata p) external;

    /// @notice Replaces every setting of a market at once, `enabled` included: this is also how a market is switched
    ///         on and off.
    /// @dev The market's id, leverage, pause and price exponent never change. Positions already open keep the terms
    ///      they were opened with. Emits {ConfigUpdated}.
    ///
    /// Requirements (in check order):
    /// - The caller holds `OPERATOR_ROLE` (`AccessControlUnauthorizedAccount`).
    /// - The market exists at this feed and leverage (`UnknownMarket`).
    /// - The settings pass `ConfigLib.validate` at the market's leverage (`InvalidLeverageParams`).
    ///
    /// @param marketId The market's Pyth feed id.
    /// @param leverage The market's leverage.
    /// @param p The market's new settings.
    function setConfig(bytes32 marketId, uint16 leverage, ConfigParams calldata p) external;

    /// @notice Pauses or unpauses one market. A paused market blocks only opens and sales: liquidations, settlements,
    ///         repayments and refunds go on, so open bets still end and IOUs are still paid (§8.10).
    /// @dev Pausing a market that is already paused succeeds and emits again. Emits {PauseChanged}.
    ///
    /// Requirements (in check order):
    /// - Pausing: the caller holds `GUARDIAN_ROLE` or `OPERATOR_ROLE` (`AccessControlUnauthorizedAccount`, naming
    ///   `GUARDIAN_ROLE`).
    /// - Unpausing: the caller holds `OPERATOR_ROLE` (`OnlyOperatorCanUnpause`).
    /// - The market exists at this feed and leverage (`UnknownMarket`).
    ///
    /// @param marketId The market's Pyth feed id.
    /// @param leverage The market's leverage: each leverage of a feed is paused on its own. The guardian's
    ///        `setHalted` stops every market at once.
    /// @param paused Whether the market should be paused.
    function setPaused(bytes32 marketId, uint16 leverage, bool paused) external;

    /// @notice Halts or resumes the whole contract: the global stop. While halted, nobody can open, sell, liquidate,
    ///         settle or repay; refunds, funding, withdrawals, claims, fee sweeps and admin work go on (§8.10).
    /// @dev Halting again succeeds and emits again. Emits {HaltChanged}.
    ///
    /// Requirements (in check order):
    /// - Halting: the caller holds `GUARDIAN_ROLE` or `OPERATOR_ROLE` (`AccessControlUnauthorizedAccount`, naming
    ///   `GUARDIAN_ROLE`).
    /// - Resuming: the caller holds `OPERATOR_ROLE` (`OnlyOperatorCanUnhalt`).
    ///
    /// @param halted Whether the contract should be halted.
    function setHalted(bool halted) external;

    /// @notice Sets the pool floor: free money below which no loser fee is taken and no withdrawal may go.
    /// @dev Emits {PoolFloorUpdated}.
    ///
    /// Requirements (in check order):
    /// - The caller holds `DEFAULT_ADMIN_ROLE` (`AccessControlUnauthorizedAccount`).
    /// - The floor is at least 500 whole tokens (`InvalidLeverageParams`).
    ///
    /// @param poolFloor The new floor, in base units of the token.
    function setPoolFloor(uint64 poolFloor) external;

    /// @notice Sets where swept fees and seed recovery go, and where rewards withdrawals go.
    /// @dev Emits {RecipientsUpdated}.
    ///
    /// Requirements (in check order):
    /// - The caller holds `DEFAULT_ADMIN_ROLE` (`AccessControlUnauthorizedAccount`).
    /// - Neither address is zero (`ZeroAddress`).
    ///
    /// @param feeRecipient Receives swept fees and seed recovery.
    /// @param rewardsRecipient Receives rewards withdrawals.
    function setRecipients(address feeRecipient, address rewardsRecipient) external;

    /// @notice Sets how long after its expiry anyone may refund a position the backend never ended (the safety
    ///         refund, `refundExpired`). 0 switches the refund off.
    /// @dev It applies to positions already open, because `refundExpired` reads it when it runs. A shorter delay lets
    ///      users take their stakes back sooner, before the backend may have ended their bets; a longer one, or 0,
    ///      keeps them waiting if the backend stops. Both are the admin's call: the 48-hour timelock on mainnet.
    ///      Emits {RefundDelayUpdated}, also when the delay doesn't change.
    ///
    /// Requirements (in check order):
    /// - The caller holds `DEFAULT_ADMIN_ROLE` (`AccessControlUnauthorizedAccount`).
    /// - The delay is 0, meaning off, or at least 1 hour (`InvalidRefundDelay`), as in `initialize`.
    ///
    /// @param refundDelaySecs The new delay after expiry, in seconds (24 hours at launch).
    function setRefundDelay(uint48 refundDelaySecs) external;

    /// @notice Sets the payout circuit breaker's limit and window: the net profit users may take out of the pool in
    ///         one window before `open` and `sell` stop (docs/ARCHITECTURE.md §8.11). A limit of 0 switches it off.
    /// @dev Raising the limit or switching the breaker off weakens a guard against a stolen relayer key, so it is the
    ///      admin's call: the 48-hour timelock on mainnet. It leaves the counters, the window start and a trip alone:
    ///      switching the breaker off doesn't clear a trip, and the operator's `resetBreaker` does. A new window
    ///      length applies to the current window at once. Emits {CircuitBreakerUpdated}, also when nothing changes.
    ///
    /// Requirements (in check order):
    /// - The caller holds `DEFAULT_ADMIN_ROLE` (`AccessControlUnauthorizedAccount`).
    /// - The window is 60 to 86,400 seconds (`InvalidBreakerParams`), as in `initialize`.
    ///
    /// @param maxNetProfit The net profit allowed out per window, in base units of the token; 0 switches it off.
    /// @param windowSecs The window's length, in seconds.
    function setBreaker(uint64 maxNetProfit, uint32 windowSecs) external;

    /// @notice Clears a trip of the payout circuit breaker, so `open` and `sell` work again, and starts a fresh
    ///         window. The operator calls it once they have checked what tripped it.
    /// @dev Both counters go to zero and the window starts at this block's second; the limit and the window's length
    ///      stay. It may be called at any time, tripped or not. Emits {CircuitBreakerReset}.
    ///
    /// Requirements:
    /// - The caller holds `OPERATOR_ROLE` (`AccessControlUnauthorizedAccount`).
    function resetBreaker() external;

    /// @notice Revokes a relayer key at once: the guardian's answer to a leaked opener or settler key. Granting a key
    ///         back needs the admin, the timelock on mainnet.
    /// @dev Emits OpenZeppelin's {RoleRevoked} if `account` held the role, and does nothing otherwise.
    ///
    /// Requirements (in check order):
    /// - The caller holds `GUARDIAN_ROLE` (`AccessControlUnauthorizedAccount`).
    /// - `role` is `OPENER_ROLE` or `SETTLER_ROLE` (`InvalidRelayerRole`).
    ///
    /// @param role The relayer role to revoke.
    /// @param account The key to revoke it from.
    function revokeRelayer(bytes32 role, address account) external;
}

src/interfaces/IManicFlashOptionErrors.s.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.38;

/// @title IManicFlashOptionErrors
/// @author Manic
/// @notice Every custom error the contract can raise, declared once. The error names are part of the public
///         interface: the backend keys off them.
/// @dev The full list of docs/ARCHITECTURE.md §11.2, with final arguments: errors that can be raised for one position
///      inside a batch carry its `positionId`, so a reverted batch names the bet that broke it and the backend can
///      drop that id and resend. Errors that fail the same way for every id carry none. An error's name and argument
///      types are part of the ABI, and test/unit/IManicFlashOptionAbi.t.sol pins every selector.
/// @custom:security-contact See SECURITY.md
interface IManicFlashOptionErrors {
    // ---------------------------------------------------------------------------------------------------------------
    // Switches and markets
    // ---------------------------------------------------------------------------------------------------------------

    /// @notice The contract is halted: only refunds, funding, withdrawals, claims, fee sweeps and admin work.
    error Halted();

    /// @notice No market has this id.
    error UnknownMarket();

    /// @notice The market is switched off, so nobody can open or sell.
    error LeverageDisabled();

    /// @notice The market is paused, so nobody can open or sell.
    error LeveragePaused();

    /// @notice The payout circuit breaker has tripped, so nobody can open or sell until the operator resets it.
    error BreakerTripped();

    // ---------------------------------------------------------------------------------------------------------------
    // Orders and signatures
    // ---------------------------------------------------------------------------------------------------------------

    /// @notice The signed order's deadline has passed.
    error OrderExpired();

    /// @notice The position id is zero or was used before. An id is single use, forever.
    error PositionIdUsed();

    /// @notice The signature is not the expected signer's: the order's user, or the position's user for a sale.
    error InvalidSignature();

    /// @notice The price tick was published before the user signed the order (before its `notBefore`).
    error PriceBeforeOrder();

    /// @notice A token pull moved a different amount than asked, for example because the token treated a reused or
    ///         cancelled authorisation as a silent no-op.
    /// @param expected The amount the contract asked for.
    /// @param received The amount its balance actually rose by.
    error TransferAmountMismatch(uint256 expected, uint256 received);

    // ---------------------------------------------------------------------------------------------------------------
    // Prices and parameters
    // ---------------------------------------------------------------------------------------------------------------

    /// @notice A price is zero or negative.
    error InvalidPrice();

    /// @notice A leverage parameter (the liquidation distance θ, the floor or the cap) is outside its allowed range.
    error InvalidLeverageParams();

    /// @notice A result does not fit its type, for example a payout above `type(uint64).max`.
    error MathOverflow();

    /// @notice An amount is zero where a positive amount is required.
    error InvalidAmount();

    // ---------------------------------------------------------------------------------------------------------------
    // Price times
    // ---------------------------------------------------------------------------------------------------------------

    /// @notice The price tick is older than the market's maximum age, or has no time at all.
    error PriceTooOld();

    /// @notice The price tick's time is ahead of the chain's clock by more than the allowed skew.
    error PriceFromFuture();

    /// @notice A liquidation's price tick is outside the position's life (before it opened or after it ended).
    /// @param positionId The position the tick can't liquidate.
    error InvalidLiquidationWindow(bytes32 positionId);

    /// @notice A liquidation's price does not touch the position's liquidation line.
    /// @param positionId The position that is not liquidated at this price.
    error LiquidationPriceNotReached(bytes32 positionId);

    /// @notice A settle's price tick is not at the position's expiry second.
    /// @param positionId The position whose expiry differs from the tick's time.
    error InvalidPriceTimestamp(bytes32 positionId);

    /// @notice The settle's price tick is ahead of the chain's clock, so the positions have not expired yet.
    error NotExpired();

    /// @notice The price touches the position's liquidation line, so it must be liquidated, not settled or sold.
    /// @param positionId The position to liquidate instead.
    error LiquidateInstead(bytes32 positionId);

    // ---------------------------------------------------------------------------------------------------------------
    // Positions and batches
    // ---------------------------------------------------------------------------------------------------------------

    /// @notice No position has this id.
    /// @param positionId The unknown id.
    error UnknownPosition(bytes32 positionId);

    /// @notice The position belongs to a different market than the batch.
    /// @param positionId The position from the other market.
    error ConfigMismatch(bytes32 positionId);

    /// @notice The position is not open, so it can't be sold.
    error PositionNotOpen();

    /// @notice The batch has no ids.
    error EmptyBatch();

    /// @notice The batch has more ids than the maximum (100).
    error BatchSizeTooLarge();

    // ---------------------------------------------------------------------------------------------------------------
    // Opening
    // ---------------------------------------------------------------------------------------------------------------

    /// @notice New positions are blocked: the total owed to winners exceeds the market's limit.
    error OpenBlockedTotalOwed();

    /// @notice New positions are blocked: the open positions' max profit would exceed the allowed share of free money.
    error OpenBlockedExposure();

    // ---------------------------------------------------------------------------------------------------------------
    // Selling
    // ---------------------------------------------------------------------------------------------------------------

    /// @notice The sale's price tick is outside the position's sell window.
    error SellWindowClosed();

    /// @notice The valuation is above what the position would pay at the current price.
    error ValuationAboveCurrentPayout();

    /// @notice The sale amount is above the valuation.
    error SellAmountExceedsValuation();

    /// @notice The early-sell fee (valuation - sale amount) is above the market's maximum.
    error SellFeeTooHigh();

    /// @notice The sale amount is below the user's signed minimum.
    error SellAmountBelowMin();

    /// @notice Winners are owed, so a sale would jump the repay queue.
    error QueueNotEmpty();

    /// @notice The pool can't pay this sale in full right now.
    error SellNotPayable();

    // ---------------------------------------------------------------------------------------------------------------
    // Repaying and refunding
    // ---------------------------------------------------------------------------------------------------------------

    /// @notice A repay call's `maxCount` is outside 1 to 50.
    error InvalidMaxCount();

    /// @notice The safety refund is switched off (its delay is 0).
    error RefundDisabled();

    /// @notice The position's expiry plus the refund delay has not passed yet.
    /// @param positionId The position that can't be refunded yet.
    error RefundTooEarly(bytes32 positionId);

    // ---------------------------------------------------------------------------------------------------------------
    // Payouts and claims
    // ---------------------------------------------------------------------------------------------------------------

    /// @notice Too little gas is left to try a payout transfer. Reverting stops a relayer from starving a payout on
    ///         purpose so that it lands in `claimable` instead of the user's wallet.
    error InsufficientGasForPayout();

    /// @notice The account has nothing to claim.
    error NothingToClaim();

    // ---------------------------------------------------------------------------------------------------------------
    // Withdrawing
    // ---------------------------------------------------------------------------------------------------------------

    /// @notice Not allowed while winners are owed.
    error OwedOutstanding();

    /// @notice The withdrawal would leave the pool's free money below its floor.
    error BelowPoolFloor();

    /// @notice The withdrawal would leave less than the floor plus every open position's max profit.
    error OpenExposureNotCovered();

    /// @notice Seed recovery would exceed 500 whole tokens in total.
    error SeedRecoveryExceeded();

    // ---------------------------------------------------------------------------------------------------------------
    // Admin
    // ---------------------------------------------------------------------------------------------------------------

    /// @notice An address that must be set is the zero address.
    error ZeroAddress();

    /// @notice The token's decimals are outside 6 to 9, so its amounts might not fit the contract's `uint64` books.
    /// @param decimals The token's decimals.
    error InvalidTokenDecimals(uint8 decimals);

    /// @notice The safety refund delay is neither 0 (off) nor at least 1 hour.
    error InvalidRefundDelay();

    /// @notice A market with this id already exists.
    error MarketExists();

    /// @notice Only the operator can unpause a market. The guardian can pause, but never resume.
    error OnlyOperatorCanUnpause();

    /// @notice Only the operator can resume a halted contract. The guardian can halt, but never resume.
    error OnlyOperatorCanUnhalt();

    /// @notice `revokeRelayer` was given a role other than `OPENER_ROLE` or `SETTLER_ROLE`. The guardian may only
    ///         revoke relayer keys; every other role is the admin's (timelocked).
    /// @param role The role that was given.
    error InvalidRelayerRole(bytes32 role);

    /// @notice The circuit breaker's window is outside 60 to 86,400 seconds.
    error InvalidBreakerParams();
}

src/interfaces/IManicFlashOptionEvents.s.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.38;

import {ConfigParams} from "../types/ParamTypes.sol";
import {Side, Status, WithdrawPurpose} from "../types/StorageTypes.sol";

/// @title IManicFlashOptionEvents
/// @author Manic
/// @notice Every event the contract emits, declared once: the positions, the pool, the markets and settings, and the
///         payout circuit breaker. `ConfigUpdated` carries the whole `ConfigParams`, and the pool floor has an event
///         of its own, `PoolFloorUpdated`.
/// @dev The field order and types are the backend's ABI: changing either is an ABI change (docs/CONVENTIONS.md §6),
///      and test/unit/IManicFlashOptionAbi.t.sol pins every event's signature. `positionId` and `user` are indexed on
///      every position event. Prices are at the market's exponent, amounts in token base units, and times in
///      seconds. OpenZeppelin's bases add `Initialized`, `Upgraded`, `RoleGranted`, `RoleRevoked`, the
///      `DefaultAdmin*` events and `EIP712DomainChanged`. A reverted transaction emits nothing.
/// @custom:security-contact See SECURITY.md
interface IManicFlashOptionEvents {
    // ---------------------------------------------------------------------------------------------------------------
    // Positions
    // ---------------------------------------------------------------------------------------------------------------

    /// @notice A position was opened, with its terms as locked on-chain.
    /// @param positionId The position's id, chosen by the backend and signed by the user.
    /// @param user The position's owner.
    /// @param marketId The market's Pyth feed id.
    /// @param side Call (Higher) or Put (Lower).
    /// @param stake The margin, in base units.
    /// @param entryPrice The entry tick's price.
    /// @param priceExponent The market's price exponent (BTC: -8).
    /// @param liqPrice The liquidation line: touching it (equality counts) loses the whole stake.
    /// @param capPrice The cap line, rounded toward the entry: the payout (stake × cap) stops growing there, or one
    ///        price unit beyond it.
    /// @param thetaE7 The liquidation distance θ × 1e7.
    /// @param floorBps The least a right call pays, in bps of the stake.
    /// @param capBps The most the position pays, in bps of the stake.
    /// @param startTime The entry tick's publish time.
    /// @param endTime The expiry second the position settles at: startTime + duration.
    /// @param leverage The bet's leverage (1000 is 1000x), copied from its market at open.
    event PositionOpened(
        bytes32 indexed positionId,
        address indexed user,
        bytes32 indexed marketId,
        Side side,
        uint64 stake,
        int64 entryPrice,
        int8 priceExponent,
        int64 liqPrice,
        int64 capPrice,
        uint32 thetaE7,
        uint16 floorBps,
        uint16 capBps,
        uint48 startTime,
        uint48 endTime,
        uint16 leverage
    );

    /// @notice A position touched its liquidation line: the user gets nothing back, and the stake stays in the pool as
    ///         free money, minus the loser fee.
    /// @param positionId The position's id.
    /// @param user The position's owner.
    /// @param side Call (Higher) or Put (Lower).
    /// @param stake The stake lost.
    /// @param liqPrice The position's liquidation line.
    /// @param price The tick that touched the line.
    /// @param publishTime The tick's publish time.
    /// @param endTime The position's expiry second.
    /// @param loserFee 3% of the stake to the fees; 0 while the pool's free money was below its floor.
    /// @param leverage The bet's leverage (1000 is 1000x), copied from its market at open.
    event PositionLiquidated(
        bytes32 indexed positionId,
        address indexed user,
        Side side,
        uint64 stake,
        int64 liqPrice,
        int64 price,
        uint48 publishTime,
        uint48 endTime,
        uint64 loserFee,
        uint16 leverage
    );

    /// @notice A position was settled at its expiry price. With `owed > 0` it became an IOU at `queueSeq`; otherwise
    ///         it closed.
    /// @param positionId The position's id.
    /// @param user The position's owner.
    /// @param side Call (Higher) or Put (Lower).
    /// @param stake The position's stake.
    /// @param finalPrice The price at the expiry second.
    /// @param publishTime The final tick's publish time, equal to the expiry second.
    /// @param gBps The payout multiple at the final price, in bps.
    /// @param payout stake × gBps / 10_000: what the position earned before fees.
    /// @param paidNow What the user receives now: the stake part plus the profit the pool could pay, minus the winner
    ///        fee.
    /// @param owed The profit recorded as an IOU; 0 when paid in full.
    /// @param queueSeq The IOU's place in the repay queue; only meaningful when `owed > 0`.
    /// @param winnerFee 2% of the profit paid now.
    /// @param loserFee 3% of the loss; 0 for a winner, or while the pool's free money was below its floor.
    /// @param leverage The bet's leverage (1000 is 1000x), copied from its market at open.
    event PositionSettled(
        bytes32 indexed positionId,
        address indexed user,
        Side side,
        uint64 stake,
        int64 finalPrice,
        uint48 publishTime,
        uint16 gBps,
        uint64 payout,
        uint64 paidNow,
        uint64 owed,
        uint64 queueSeq,
        uint64 winnerFee,
        uint64 loserFee,
        uint16 leverage
    );

    /// @notice A position was sold early and closed.
    /// @param positionId The position's id.
    /// @param user The position's owner.
    /// @param side Call (Higher) or Put (Lower).
    /// @param stake The position's stake.
    /// @param price The sale's tick price.
    /// @param publishTime The sale's tick publish time.
    /// @param gNowBps The payout multiple at the sale's price, in bps.
    /// @param valuation What the sale is worth before the early-sell fee: sellAmount + sellFee.
    /// @param sellAmount The sale price; the user receives it minus `winnerFee`.
    /// @param sellFee The early-sell fee: valuation - sellAmount.
    /// @param winnerFee 2% of the profit (sellAmount - stake) on a profitable sale.
    /// @param loserFee 3% of the loss (stake - valuation) on a losing sale; 0 below the pool's floor.
    /// @param leverage The bet's leverage (1000 is 1000x), copied from its market at open.
    event PositionSold(
        bytes32 indexed positionId,
        address indexed user,
        Side side,
        uint64 stake,
        int64 price,
        uint48 publishTime,
        uint16 gNowBps,
        uint64 valuation,
        uint64 sellAmount,
        uint64 sellFee,
        uint64 winnerFee,
        uint64 loserFee,
        uint16 leverage
    );

    /// @notice An IOU was repaid, in full (`remainingOwed == 0`, it closes) or in part (it stays at the head of the
    ///         queue).
    /// @param positionId The IOU's position.
    /// @param user The position's owner.
    /// @param queueSeq The IOU's place in the repay queue.
    /// @param amount Taken off the IOU; the user receives it minus `winnerFee`.
    /// @param winnerFee 2% of `amount`.
    /// @param remainingOwed What is still owed.
    event OwedRepaid(
        bytes32 indexed positionId,
        address indexed user,
        uint64 queueSeq,
        uint64 amount,
        uint64 winnerFee,
        uint64 remainingOwed
    );

    /// @notice A position was skipped by a batch because it had already ended, for example sold in the same block.
    ///         A batch skips such ids instead of reverting.
    /// @param positionId The skipped position.
    /// @param status Its status when skipped: `Owed` or `Closed`.
    event PositionSkipped(bytes32 indexed positionId, Status status);

    /// @notice A position still open long after its expiry was refunded its stake, because the backend never ended it
    ///         (the safety refund).
    /// @param positionId The refunded position.
    /// @param user The position's owner, who receives the stake.
    /// @param stake The stake returned.
    event PositionRefunded(bytes32 indexed positionId, address indexed user, uint64 stake);

    // ---------------------------------------------------------------------------------------------------------------
    // The pool
    // ---------------------------------------------------------------------------------------------------------------

    /// @notice Money was added to the pool as free money.
    /// @param actor Who funded it.
    /// @param amount The amount added, in base units.
    event PoolFunded(address indexed actor, uint64 amount);

    /// @notice The admin took free money out of the pool.
    /// @param purpose Seed recovery (to the fee recipient) or rewards (to the rewards recipient).
    /// @param amount The amount withdrawn, in base units.
    /// @param destination The recipient it was sent to.
    event PoolWithdrawn(WithdrawPurpose purpose, uint64 amount, address indexed destination);

    /// @notice A payout couldn't be transferred (for example, the recipient is frozen), so it was credited to the
    ///         recipient's claimable balance instead.
    /// @param positionId The position the payout was for.
    /// @param to The recipient, who can claim it later.
    /// @param amount The amount credited.
    event PayoutDeferred(bytes32 indexed positionId, address indexed to, uint64 amount);

    /// @notice A claimable balance was paid out.
    /// @param account The account paid; a claim only ever pays the account itself.
    /// @param amount The amount paid.
    event Claimed(address indexed account, uint64 amount);

    /// @notice The accrued fees were sent to the fee recipient.
    /// @param to The fee recipient.
    /// @param amount The amount sent.
    event FeesSwept(address indexed to, uint64 amount);

    // ---------------------------------------------------------------------------------------------------------------
    // Markets and settings
    // ---------------------------------------------------------------------------------------------------------------

    /// @notice A market was created, switched off.
    /// @param marketId The market's Pyth feed id.
    /// @param leverage The market's leverage; with `marketId`, the market's key (ADR 0008).
    /// @param index The market's index in storage, which positions record.
    /// @param priceExponent The market's price exponent, fixed for its life.
    event MarketCreated(bytes32 indexed marketId, uint16 indexed leverage, uint16 index, int8 priceExponent);

    /// @notice A market's settings were replaced. Carries every setting as it is after the change, so a reader never
    ///         needs the earlier state.
    /// @param marketId The market's Pyth feed id.
    /// @param leverage The market's leverage.
    /// @param actor Who changed it.
    /// @param params The market's settings after the change.
    event ConfigUpdated(bytes32 indexed marketId, uint16 indexed leverage, address indexed actor, ConfigParams params);

    /// @notice A market was paused or unpaused.
    /// @param marketId The market's Pyth feed id.
    /// @param leverage The market's leverage.
    /// @param actor Who changed it.
    /// @param paused Whether the market is now paused.
    event PauseChanged(bytes32 indexed marketId, uint16 indexed leverage, address indexed actor, bool paused);

    /// @notice The whole contract was halted or resumed.
    /// @param actor Who changed it.
    /// @param halted Whether the contract is now halted.
    event HaltChanged(address indexed actor, bool halted);

    /// @notice The pool's floor changed.
    /// @param poolFloor The new floor, in base units.
    event PoolFloorUpdated(uint64 poolFloor);

    /// @notice The fee and rewards recipients changed.
    /// @param feeRecipient The new fee recipient.
    /// @param rewardsRecipient The new rewards recipient.
    event RecipientsUpdated(address indexed feeRecipient, address indexed rewardsRecipient);

    /// @notice The safety refund delay changed.
    /// @param refundDelaySecs The new delay after expiry, in seconds; 0 switches the refund off.
    event RefundDelayUpdated(uint48 refundDelaySecs);

    // ---------------------------------------------------------------------------------------------------------------
    // The payout circuit breaker
    // ---------------------------------------------------------------------------------------------------------------

    /// @notice The circuit breaker's limit or window changed.
    /// @param maxNetProfit The net profit allowed out per window, in base units; 0 switches the breaker off.
    /// @param windowSecs The window's length, in seconds.
    event CircuitBreakerUpdated(uint64 maxNetProfit, uint32 windowSecs);

    /// @notice The circuit breaker tripped: open and sell are blocked until the operator resets it.
    /// @param profitOut The profit paid to users in the window.
    /// @param lossIn The losers' losses kept by the pool in the window.
    /// @param windowStart When the window started.
    event CircuitBreakerTripped(uint64 profitOut, uint64 lossIn, uint48 windowStart);

    /// @notice The operator reset the circuit breaker, starting a fresh window.
    /// @param actor Who reset it.
    event CircuitBreakerReset(address indexed actor);
}

src/interfaces/IManicFlashOptionPool.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.38;

import {WithdrawPurpose} from "../types/StorageTypes.sol";

/// @title IManicFlashOptionPool
/// @author Manic
/// @notice The pool's money in and out: funding, the admin's withdrawals, claims of payouts that waited, and fee sweeps
///         (docs/ARCHITECTURE.md §8.1, §8.8). Implemented by `PoolModule`.
/// @dev Every function here works while the contract is halted or a market is paused (§8.10). The books these change
///      are in `PoolState`: `total` is held stakes plus free money, and `feesPending` and `totalClaimable` are kept
///      apart from it, so the contract's balance always covers `total + feesPending + totalClaimable` (§9).
/// @custom:security-contact See SECURITY.md
interface IManicFlashOptionPool {
    /// @notice Adds money to the pool as free money: the launch seed, or a top-up later. Anyone may fund it.
    /// @dev Pulls `amount` from the caller with `transferFrom`, so the caller must have approved it first, then checks
    ///      the contract's balance rose by exactly `amount`. Emits {PoolFunded}.
    ///
    /// Requirements (in check order):
    /// - `amount` is not zero (`InvalidAmount`).
    /// - The pool's total stays within 64 bits (`MathOverflow`).
    /// - The pull succeeds (the token's own error otherwise).
    /// - The balance rises by exactly `amount` (`TransferAmountMismatch`): a token that takes a fee, or moves nothing,
    ///   is refused.
    ///
    /// @param amount The amount to add, in base units of the token.
    function fund(uint64 amount) external;

    /// @notice Takes free money out of the pool: the launch seed back (to the fee recipient), or money for rewards (to
    ///         the rewards recipient).
    /// @dev Never touches the stakes of open bets, and keeps every open bet's max profit covered above the floor.
    ///      Emits {PoolWithdrawn}, then sends the amount; a failed transfer reverts everything.
    ///
    /// Requirements (in check order, `LeverageMath.checkWithdraw` after the role):
    /// - The caller holds `DEFAULT_ADMIN_ROLE` (`AccessControlUnauthorizedAccount`).
    /// - `amount` is not zero (`InvalidAmount`).
    /// - Nobody is owed (`OwedOutstanding`).
    /// - Free money stays at or above the floor (`BelowPoolFloor`).
    /// - What stays above the floor still covers every open bet's max profit (`OpenExposureNotCovered`).
    /// - Seed recovery stays within 500 whole tokens in total (`SeedRecoveryExceeded`).
    ///
    /// @param purpose Seed recovery or rewards; it decides the recipient and the counter.
    /// @param amount The amount to withdraw, in base units.
    function withdraw(WithdrawPurpose purpose, uint64 amount) external;

    /// @notice Pays an account the payouts that waited for it because their transfer failed (for example while it was
    ///         frozen). Anyone may call it, but the money only ever goes to `account`.
    /// @dev Emits {Claimed}, then sends the balance. If the transfer fails, everything reverts and the balance stays
    ///      claimable.
    ///
    /// Requirements (in check order):
    /// - `account` has a claimable balance (`NothingToClaim`).
    /// - The transfer to `account` succeeds (the token's own error otherwise).
    ///
    /// @param account The account to pay.
    function claim(address account) external;

    /// @notice Sends every accrued fee to the fee recipient. Anyone may call it. Fees accrue apart from the pool, so a
    ///         blocked fee recipient never stops a bet from ending.
    /// @dev Emits {FeesSwept}, then sends the fees. If the transfer fails, everything reverts and the fees stay
    ///      pending; the admin can change the recipient.
    ///
    /// Requirements (in check order):
    /// - Some fees are pending (`InvalidAmount`).
    /// - The transfer to the fee recipient succeeds (the token's own error otherwise).
    function sweepFees() external;
}

src/interfaces/IManicFlashOptionRoles.so.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.38;

// The getters keep the constants' UPPER_SNAKE names (see @dev below), so the mixed-case lints are off in this file.
/* solhint-disable func-name-mixedcase */
// forge-lint: disable-start(mixed-case-function)

/// @title IManicFlashOptionRoles
/// @author Manic
/// @notice The ids of the contract's roles, for OpenZeppelin's `hasRole`, `grantRole` and `revokeRole`. Who holds each
///         role on mainnet, and what it may do, is in docs/ARCHITECTURE.md §4.2.
/// @dev Each id is the keccak256 of its name (OpenZeppelin's convention), and `DEFAULT_ADMIN_ROLE` is 0x00. Every
///      role's admin is `DEFAULT_ADMIN_ROLE`, which only one account holds: the 48-hour timelock on mainnet. The
///      getters keep the constants' UPPER_SNAKE names, as OpenZeppelin's own `DEFAULT_ADMIN_ROLE()` does, so the
///      mixed-case lints are switched off for this file.
/// @custom:security-contact See SECURITY.md
interface IManicFlashOptionRoles {
    /// @notice The upgrader: the only role that can upgrade the implementation. The timelock on mainnet.
    /// @return The role's id: keccak256("UPGRADER_ROLE").
    function UPGRADER_ROLE() external view returns (bytes32);

    /// @notice The operator: market settings, enabling markets, unpausing, unhalting and resetting the circuit
    ///         breaker. None of these moves money. The admin Safe on mainnet, acting at once.
    /// @return The role's id: keccak256("OPERATOR_ROLE").
    function OPERATOR_ROLE() external view returns (bytes32);

    /// @notice The guardian: halts the contract, pauses a market and revokes a relayer key. It can only take power
    ///         away, never add it.
    /// @return The role's id: keccak256("GUARDIAN_ROLE").
    function GUARDIAN_ROLE() external view returns (bytes32);

    /// @notice The opening relayer: the backend accounts that open and sell positions. It is trusted for the price
    ///         only.
    /// @return The role's id: keccak256("OPENER_ROLE").
    function OPENER_ROLE() external view returns (bytes32);

    /// @notice The settling relayer: the backend accounts that liquidate and settle positions, kept separate from the
    ///         openers so that one leaked key can't do both.
    /// @return The role's id: keccak256("SETTLER_ROLE").
    function SETTLER_ROLE() external view returns (bytes32);
}
// forge-lint: disable-end(mixed-case-function)

src/interfaces/IManicFlashOptionSettleme.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.38;

/// @title IManicFlashOptionSettlement
/// @author Manic
/// @notice How positions end at a price, how a position the backend never ended is refunded, and how the winners the
///         pool couldn't pay are paid later. The settler relayer liquidates positions when a tick touches their line
///         and settles them at their expiry second, in batches of up to 100 positions of one market (one feed at one
///         leverage) at one price tick (docs/ARCHITECTURE.md §8.4, §8.5). Anyone refunds the stake of a position
///         still open long after its expiry (the safety refund, §8.6), and anyone repays the IOU queue from the
///         pool's free money (§8.7). Implemented by `SettlementModule`.
/// @dev The settler is trusted for the price only: each position's own times and line are
///      checked against the tick. `liquidate`, `settle` and `repay` work while a market is paused or switched off,
///      and while the circuit breaker is tripped; only the halt stops them (§8.10), so a bet can always end once the
///      operator releases the halt. No brake stops `refundExpired`, which only ever returns a user's own stake.
///
///      A batch skips any position that has already ended, with {PositionSkipped}: sold, liquidated, settled or
///      refunded earlier, or listed twice in the same batch. An id that was never opened, or a position of another
///      market, still reverts the whole batch, with the id in the error, so the backend can drop it and resend.
///
///      Free money is measured position by position, in batch order: an earlier position's released stake or loss
///      counts for the next one's loser fee and payout. Fees accrue in the pool's pending fees
///      once per batch; anyone sweeps them to the fee recipient later (`sweepFees`). `liquidate`, `settle` and
///      `repay` also count their users' winnings and losses in the payout circuit breaker once per call (§8.11);
///      a refund counts nothing.
/// @custom:security-contact See SECURITY.md
interface IManicFlashOptionSettlement {
    /// @notice Liquidates every position in `ids` whose liquidation line the tick touches: the user gets nothing back,
    ///         and the stake stays in the pool as free money, less the 3% loser fee while free money is at or above
    ///         the floor.
    /// @dev For each position, in order: free money is measured with its stake still held, the stake and its max
    ///      profit are released, the loser fee leaves the pool's total, and the position closes (slot 0 stays as the
    ///      tombstone, slot 1 is cleared). Emits {PositionLiquidated} per position ended and {PositionSkipped} per
    ///      position that had already ended. After the loop, the batch's fees are added to the pending fees and to
    ///      `feesPaid`, and its liquidated stakes are counted as losses in the payout circuit breaker (§8.11). No
    ///      tokens move. Old ticks are accepted, so the backend can catch up after an outage.
    ///
    /// Requirements (in check order):
    /// - The caller holds `SETTLER_ROLE` (`AccessControlUnauthorizedAccount`).
    /// - The contract is not halted (`Halted`).
    /// - `ids` has 1 to 100 ids (`EmptyBatch` / `BatchSizeTooLarge`).
    /// - The market exists at this feed and leverage (`UnknownMarket`).
    /// - For each id, in order: it was opened (`UnknownPosition(id)`) on this market, so at this leverage
    ///   (`ConfigMismatch(id)`); if it is still open, then the price is positive (`InvalidPrice`), the tick is inside
    ///   the position's life, both ends included (`InvalidLiquidationWindow(id)`), and at most the market's clock skew
    ///   ahead of the chain's clock (`PriceFromFuture`), and the price touches the line, equality included
    ///   (`LiquidationPriceNotReached(id)`).
    /// - The pool's books stay within their types (`MathOverflow`).
    ///
    /// @param marketId The market's Pyth feed id; every position in `ids` must belong to it.
    /// @param leverage The market's leverage; every position in `ids` must have been opened at it.
    /// @param price The tick's price, at the market's exponent.
    /// @param publishTime The tick's publish time.
    /// @param ids The positions to liquidate.
    /// @return processed The number of positions liquidated; skipped ids are not counted.
    function liquidate(
        bytes32 marketId,
        uint16 leverage,
        int64 price,
        uint48 publishTime,
        bytes32[] calldata ids
    )
        external
        returns (uint256 processed);

    /// @notice Settles every position in `ids` that expires at the tick's second, at the tick's price: each pays
    ///         `stake × g`, with the floor and the cap applied, less the 2% winner fee on the profit paid now, or the
    ///         3% loser fee on a loss while free money is at or above the floor. Profit the pool can't pay now becomes
    ///         an IOU at the back of the repay queue.
    /// @dev For each position, in order: g and the payout at the tick's price, at the market's leverage; the split with
    ///      free money measured
    ///      with its stake still held (while anyone is owed, a new winner's whole profit is queued, so nobody jumps
    ///      the queue); the stake and its max profit released; what leaves the pool (the user's part and both fees)
    ///      leaves its total. With nothing owed, the position closes (slot 0 stays as the tombstone, slot 1 is
    ///      cleared). With profit owed, it becomes an IOU: the next queue number, the total owed, the IOU count and
    ///      slot 2 are written, and slot 1 is kept. Then {PositionSettled} is emitted, and the user's part is paid
    ///      through `_pay`: if the token refuses the transfer (a frozen user, a paused token), it waits in the user's
    ///      claimable balance ({PayoutDeferred}), and the rest of the batch goes on. Emits {PositionSkipped} per
    ///      position that had already ended. After the loop, the batch's fees are added to the pending fees and to
    ///      `feesPaid`, and its profit paid now and its losses are counted in the payout circuit breaker, which may
    ///      trip ({CircuitBreakerTripped}, after the batch's other events; §8.11). Old ticks are accepted, so the
    ///      backend can catch up after an outage.
    ///
    /// Requirements (in check order):
    /// - The caller holds `SETTLER_ROLE` (`AccessControlUnauthorizedAccount`).
    /// - The contract is not halted (`Halted`).
    /// - `ids` has 1 to 100 ids (`EmptyBatch` / `BatchSizeTooLarge`).
    /// - The market exists at this feed and leverage (`UnknownMarket`).
    /// - The price is positive (`InvalidPrice`).
    /// - The tick is at most the market's clock skew ahead of the chain's clock, so the second has passed
    ///   (`NotExpired`).
    /// - For each id, in order: it was opened (`UnknownPosition(id)`) on this market, so at this leverage
    ///   (`ConfigMismatch(id)`); if it is still open, then it expires at exactly the tick's second
    ///   (`InvalidPriceTimestamp(id)`), and the price doesn't touch its line (`LiquidateInstead(id)`: such a position
    ///   is liquidated at the same tick).
    /// - The pool's books stay within their types (`MathOverflow`).
    /// - Each payout has at least 60,000 gas, and doesn't run out of gas (`InsufficientGasForPayout`).
    ///
    /// @param marketId The market's Pyth feed id; every position in `ids` must belong to it.
    /// @param leverage The market's leverage; every position in `ids` must have been opened at it.
    /// @param price The price at the close of the expiry second, at the market's exponent.
    /// @param publishTime The tick's publish time: the positions' expiry second.
    /// @param ids The positions to settle.
    /// @return processed The number of positions settled, IOUs included; skipped ids are not counted.
    function settle(
        bytes32 marketId,
        uint16 leverage,
        int64 price,
        uint48 publishTime,
        bytes32[] calldata ids
    )
        external
        returns (uint256 processed);

    /// @notice Returns the stake of every position in `ids` that is still open once the refund delay has passed since
    ///         its expiry: the safety refund, for a bet the backend never ended. Anyone may call it, and no brake
    ///         stops it.
    /// @dev For each position, in order: its stake and max profit are released, the stake leaves the pool's total, and
    ///      the position closes (slot 0 stays as the tombstone, slot 1 is cleared). Then {PositionRefunded} is
    ///      emitted, and the whole stake is paid back through `_pay`: no fee is taken, and if the token refuses the
    ///      transfer (a frozen user, a paused token), it waits in the user's claimable balance ({PayoutDeferred}),
    ///      and the rest of the batch goes on. Free money doesn't change: the stake was held for the position and
    ///      leaves with it, so the payout circuit breaker counts nothing. Emits {PositionSkipped} per position that
    ///      had already ended.
    ///
    ///      The delay is read when the refund runs, so a change by `setRefundDelay` applies to positions already
    ///      open. Once the delay has passed, `settle` and `liquidate` can still end a position too; whichever lands
    ///      first ends it, and the other skips it. The backend settles within seconds of expiry, so this only
    ///      matters after an outage of at least the delay (24 hours by default).
    ///
    /// Requirements (in check order):
    /// - The refund is switched on: its delay is not 0 (`RefundDisabled`).
    /// - `ids` has 1 to 100 ids (`EmptyBatch` / `BatchSizeTooLarge`).
    /// - For each id, in order: it was opened (`UnknownPosition(id)`), on any market; if it is still open, then at
    ///   least the refund delay has passed since its expiry, `block.timestamp ≥ endTime + refundDelaySecs`
    ///   (`RefundTooEarly(id)`).
    /// - The pool's books stay within their types (`MathOverflow`).
    /// - Each payout has at least 60,000 gas, and doesn't run out of gas (`InsufficientGasForPayout`).
    ///
    /// @param ids The positions to refund. They may belong to different markets.
    /// @return processed The number of positions refunded; skipped ids are not counted.
    function refundExpired(bytes32[] calldata ids) external returns (uint256 processed);

    /// @notice Repays the IOU queue out of the pool's free money, strictly in queue order, from the head. Anyone may
    ///         call it: the backend after each settle batch, or an owner waiting to be paid.
    /// @dev Each repayment pays the head as much as free money allows, less the 2% winner fee (`repaySplit`): the
    ///      amount leaves the pool's total and its total owed, and the IOU's `owed` drops by it. Only free money
    ///      repays, so the stakes of open bets are never touched.
    ///
    ///      A head paid in full leaves the queue: the owed count drops, the head moves on to the next IOU, its queue
    ///      entry is deleted, and the position closes (slot 0 stays as the tombstone; slots 1 and 2 are cleared). The
    ///      first IOU that free money covers only in part keeps the rest owed and stays at the head, and the call
    ///      stops there. The call also stops when free money runs out, when the queue is empty, and after `maxCount`
    ///      repayments, so with an empty queue or no free money it changes nothing.
    ///
    ///      Emits {OwedRepaid} per repayment, then pays the owner through `_pay`: if the token refuses the transfer
    ///      (a frozen owner, a paused token), it waits in the owner's claimable balance ({PayoutDeferred}), and the
    ///      rest of the queue is still paid. After the loop, the winner fees are added to the pending fees and to
    ///      `feesPaid`, and the amounts repaid are counted as profit in the payout circuit breaker, which may trip
    ///      ({CircuitBreakerTripped}; §8.11).
    ///
    /// Requirements (in check order):
    /// - The contract is not halted (`Halted`).
    /// - `maxCount` is 1 to 50 (`InvalidMaxCount`).
    /// - The pool's books stay within their types (`MathOverflow`).
    /// - Each payout has at least 60,000 gas, and doesn't run out of gas (`InsufficientGasForPayout`).
    ///
    /// @param maxCount The most IOUs to repay in this call.
    /// @return repaid The number of IOUs repaid: each was paid in full, except perhaps the last, which may have been
    ///         paid in part and is then the new head.
    function repay(uint256 maxCount) external returns (uint256 repaid);
}

src/interfaces/IManicFlashOptionTrading..content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.38;

import {OpenOrder, OpenTerms, SellOrder, SellTerms, StakeAuth} from "../types/OrderTypes.sol";

/// @title IManicFlashOptionTrading
/// @author Manic
/// @notice Opening positions and selling them early: what the opener relayer calls with a user's signed order and the
///         price tick it saw (docs/ARCHITECTURE.md §8.2, §8.3). Implemented by `TradingModule`.
/// @dev The relayer is trusted for the price only: everything else it supplies is checked
///      against the user's signature or the market's bounds.
/// @custom:security-contact See SECURITY.md
interface IManicFlashOptionTrading {
    /// @notice Opens a position: the user's signed order, at the price the relayer saw.
    /// @dev Records the position (stake held, lines locked), adds the stake to the pool's total and its held margin and
    ///      the position's max profit to the open max profit, emits {PositionOpened}, and only then pulls the stake
    ///      with the user's EIP-3009 authorisation, `a`, whose nonce is the position id. A failed pull reverts all of
    ///      it. The position's clock starts at the entry tick, not when the transaction lands.
    ///
    /// Requirements (in check order):
    /// - The caller holds `OPENER_ROLE` (`AccessControlUnauthorizedAccount`).
    /// - The contract is not halted (`Halted`).
    /// - The order has not expired: `block.timestamp` ≤ `o.deadline` (`OrderExpired`).
    /// - The market of the order's feed at the order's leverage exists (`UnknownMarket`), is enabled
    ///   (`LeverageDisabled`) and is not paused (`LeveragePaused`), and the circuit breaker has not tripped
    ///   (`BreakerTripped`).
    /// - `o.positionId` is not zero and was never used (`PositionIdUsed`).
    /// - `signature` is `o.user`'s signature of the order (`InvalidSignature`).
    /// - The terms fit the market: the stake (`InvalidAmount`); an enabled duration, θ inside its rule, the floor, and
    ///   a cap of at least the floor (`InvalidLeverageParams`).
    /// - The entry tick is at most the market's maximum age old (`PriceTooOld`) and at most its clock skew ahead
    ///   (`PriceFromFuture`).
    /// - The entry tick is at or after `o.notBefore`, so the user signed before the price was known
    ///   (`PriceBeforeOrder`).
    /// - The entry price is positive and the lines fit (`InvalidPrice` / `InvalidLeverageParams`).
    /// - The open gate lets the bet in (`OpenBlockedTotalOwed` / `OpenBlockedExposure`).
    /// - The pool's books stay within their types (`MathOverflow`).
    /// - The token moves exactly `o.stake` from `o.user` (the token's own error, or `TransferAmountMismatch`). USDG
    ///   names its own bad-signature error `InvalidSignature` too; this function checks the order's signature first.
    ///
    /// @param o The order, signed by the user before the price was known.
    /// @param signature `o.user`'s signature of `o` (EIP-712), 65 bytes from an EOA.
    /// @param t The terms the relayer adds at the tick: the entry price and time, θ, the floor and the cap.
    /// @param a The user's EIP-3009 authorisation for exactly `o.stake`, with `o.positionId` as its nonce.
    function open(OpenOrder calldata o, bytes calldata signature, OpenTerms calldata t, StakeAuth calldata a) external;

    /// @notice Sells a position before its expiry: the user's signed order, at the price and the amounts the relayer
    ///         quotes.
    /// @dev The relayer quotes the valuation (what the position is worth at the tick) and the sale amount (the
    ///      valuation less the early-sell fee); the contract bounds both with its own maths, and the user's
    ///      `minAmount` bounds the sale amount from below. A sale is never partly paid: it goes through only while
    ///      nobody is owed and the pool can pay the whole valuation now, so it can never jump the repay queue.
    ///
    ///      The position closes: its stake and max profit are released, the valuation and the loser fee leave the
    ///      pool's total, and the early-sell, winner and loser fees go into the pending fees. Then {PositionSold} is
    ///      emitted, the sale amount against the stake is counted in the payout circuit breaker as a profit or a
    ///      loss, which may trip it ({CircuitBreakerTripped}; §8.11), and the user is paid the sale amount less the
    ///      winner fee through `_pay`: if the token refuses the transfer (a frozen user, a paused token), it waits in
    ///      the user's claimable balance ({PayoutDeferred}). A sale closes its position, so its order can never be
    ///      used again.
    ///
    /// Requirements (in check order):
    /// - The caller holds `OPENER_ROLE` (`AccessControlUnauthorizedAccount`).
    /// - The contract is not halted (`Halted`).
    /// - The order has not expired: `block.timestamp` ≤ `s.deadline` (`OrderExpired`).
    /// - The position exists (`UnknownPosition(id)`). Its market is enabled (`LeverageDisabled`) and not paused
    ///   (`LeveragePaused`), and the circuit breaker has not tripped (`BreakerTripped`).
    /// - The position is open (`PositionNotOpen`).
    /// - `signature` is the position's user's signature of the order (`InvalidSignature`).
    /// - The tick is inside the sell window: at least the market's minimum delay after the start, and more than its
    ///   cutoff before the end; and the sale lands before the end, `block.timestamp < endTime` (`SellWindowClosed`
    ///   for either).
    /// - The tick is at most the market's maximum age old (`PriceTooOld`) and at most its clock skew ahead
    ///   (`PriceFromFuture`).
    /// - The tick is at or after `s.notBefore`, so the user signed before the price was known (`PriceBeforeOrder`).
    /// - The price is positive (`InvalidPrice`) and doesn't touch the position's line (`LiquidateInstead(id)`).
    /// - The valuation is at most what the position pays at this price (`ValuationAboveCurrentPayout`); the sale
    ///   amount at most the valuation (`SellAmountExceedsValuation`); the early-sell fee at most the market's cap
    ///   (`SellFeeTooHigh`); the sale amount at least `s.minAmount` (`SellAmountBelowMin`); nobody is owed
    ///   (`QueueNotEmpty`); and the valuation within free money plus the position's own stake (`SellNotPayable`).
    /// - The pool's books stay within their types (`MathOverflow`).
    /// - The payout has at least 60,000 gas, and doesn't run out of gas (`InsufficientGasForPayout`).
    ///
    /// @param s The order, signed by the position's user before the price was known.
    /// @param signature The position's user's signature of `s` (EIP-712), 65 bytes from an EOA.
    /// @param t The terms the relayer adds at the tick: the price and its time, the valuation and the sale amount.
    function sell(SellOrder calldata s, bytes calldata signature, SellTerms calldata t) external;
}

src/interfaces/IManicFlashOptionViews.so.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.38;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {OpenOrder, SellOrder} from "../types/OrderTypes.sol";
import {Breaker, Market, PoolState, Position} from "../types/StorageTypes.sol";

/// @title IManicFlashOptionViews
/// @author Manic
/// @notice The contract's read-only functions (docs/ARCHITECTURE.md §8.9): the positions, the markets, the pool's
///         books, the repay queue, the circuit breaker and the settings, and the EIP-712 hash helpers.
/// @dev Every getter that reads the contract's storage reverts with `ReentrancyGuardReentrantCall` while one of the
///      contract's state-changing functions is running, so a contract that reads them from inside a call into this one
///      (a token callback) can never see half-updated books (read-only reentrancy, §15 rule 12). Off-chain reads and
///      ordinary calls are never affected.
/// @custom:security-contact See SECURITY.md
interface IManicFlashOptionViews {
    /// @notice The EIP-712 digest a user signs to open a position, so the backend can check its own encoding against
    ///         the contract's.
    /// @dev The order's struct hash under this contract's domain: the name "Manic Flash Option", version "1", the chain
    ///      id and this proxy's address. The same order gives another digest on another chain or another deployment,
    ///      so a signature can never be replayed there.
    /// @param o The order.
    /// @return The digest the user's signature must sign.
    function hashOpenOrder(OpenOrder calldata o) external view returns (bytes32);

    /// @notice The EIP-712 digest a position's user signs to sell it early.
    /// @dev The same as `hashOpenOrder`, for a `SellOrder`.
    /// @param s The order.
    /// @return The digest the user's signature must sign.
    function hashSellOrder(SellOrder calldata s) external view returns (bytes32);

    /// @notice A position as stored, with its expiry second and its cap price.
    /// @dev An id that was never used returns an empty record, `status` `None`: that is how to tell an id is free.
    ///      A closed position keeps only its first slot (the user, the market, the side, the status, the start and the
    ///      duration); its stake, prices, floor and cap read 0, and so does its cap price. An IOU keeps its terms and
    ///      also reads `owed` and `queueSeq`. The cap price isn't stored: it is recomputed from the entry, the side,
    ///      the cap and the leverage of the bet's market (`LeverageMath.capLine`), which gives the value
    ///      {PositionOpened} reported.
    /// @param positionId The position's id.
    /// @return position The stored position.
    /// @return endTime Its expiry second: `startTime + durationSecs`.
    /// @return capPrice The cap line, rounded toward the entry (the payout may reach its cap one price unit beyond
    ///         it); 0 when its terms are cleared.
    function getPosition(bytes32 positionId)
        external
        view
        returns (Position memory position, uint48 endTime, int64 capPrice);

    /// @notice A market's settings, its leverage included.
    /// @dev Reverts `UnknownMarket` for a feed and leverage that no market has.
    /// @param marketId The market's Pyth feed id.
    /// @param leverage The market's leverage.
    /// @return The market.
    function getMarket(bytes32 marketId, uint16 leverage) external view returns (Market memory);

    /// @notice The key of the market at `index`, the index positions record: its feed and its leverage. Markets are
    ///         numbered from 0 in the order they were created.
    /// @dev Reverts `UnknownMarket` for an index at or above `marketCount()`.
    /// @param index The market's index.
    /// @return marketId The market's Pyth feed id.
    /// @return leverage The market's leverage.
    function marketIdAt(uint16 index) external view returns (bytes32 marketId, uint16 leverage);

    /// @notice How many markets have been created; their indexes run from 0 to this less one.
    /// @return The number of markets.
    function marketCount() external view returns (uint16);

    /// @notice The pool's books: every field of `PoolState`.
    /// @dev The contract's token balance always covers `total + feesPending + totalClaimable` (§9).
    /// @return The books.
    function getPool() external view returns (PoolState memory);

    /// @notice The pool's free money: its total less the stakes of open bets. What new bets' max profit, repayments
    ///         and withdrawals are measured against.
    /// @return `total - lockedMargin`.
    function freeMoney() external view returns (uint64);

    /// @notice What waits for `account` to claim: payouts whose transfer the token refused.
    /// @param account The account.
    /// @return Its claimable balance, which `claim(account)` pays.
    function claimableOf(address account) external view returns (uint64);

    /// @notice The head of the repay queue: the IOU `repay` pays next.
    /// @dev With nobody owed, it returns the next place and no position: `(nextRepaySeq, 0, 0)`.
    /// @return queueSeq The head's place in the queue.
    /// @return positionId The head's position, or 0 if the queue is empty.
    /// @return owed What the head is still owed, or 0 if the queue is empty.
    function queueHead() external view returns (uint64 queueSeq, bytes32 positionId, uint64 owed);

    /// @notice The payout circuit breaker: its window, its counters, its limit and whether it has tripped (§8.11).
    /// @return The breaker.
    function getBreaker() external view returns (Breaker memory);

    /// @notice The stablecoin the pool holds and pays in (USDG), set at initialisation.
    /// @return The token.
    function token() external view returns (IERC20);

    /// @notice Whether the guardian or the operator has halted the contract: no bet opens, sells or ends, and no IOU
    ///         is repaid, until the operator releases it (§8.10).
    /// @return True while halted.
    function halted() external view returns (bool);

    /// @notice How long after its expiry anyone may refund a position that was never ended (the safety refund).
    /// @return The delay in seconds; 0 when the refund is switched off.
    function refundDelaySecs() external view returns (uint48);

    /// @notice Where money leaves the pool to.
    /// @return feeRecipient Receives swept fees and seed recovery.
    /// @return rewardsRecipient Receives rewards withdrawals.
    function recipients() external view returns (address feeRecipient, address rewardsRecipient);

    /// @notice The version of the implementation behind the proxy.
    /// @dev Each upgrade raises it, so a script can check which code a proxy runs.
    /// @return The version string, `"1.0.0"` for the first release.
    function version() external pure returns (string memory);
}

src/interfaces/external/IUSDG.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.38;

/// @title IUSDG
/// @author Manic
/// @notice The one USDG function the contract calls beyond ERC-20: EIP-3009's `receiveWithAuthorization`, in the form
///         that takes the signature as bytes, so a contract wallet's (ERC-1271) authorisation works too.
/// @dev Paxos's USDG on Robinhood Chain is built from facets. This form's selector, `0x88b7ab63`, is registered to its
///      EIP-3009 facet (checked live on mainnet 4663, 2026-11-11). Only the payee, `to`, may submit it, so nobody can
///      front-run the contract's pull. A nonce that was already used or cancelled is a silent no-op: no revert and no
///      transfer. That is why `open` checks its own balance afterwards (docs/ARCHITECTURE.md §8.2).
/// @custom:security-contact See SECURITY.md
interface IUSDG {
    /// @notice Moves `value` from `from` to the caller, with `from`'s signed authorisation.
    /// @param from The authorising holder.
    /// @param to The payee, which must be the caller.
    /// @param value The amount, in base units.
    /// @param validAfter The authorisation is valid only after this time.
    /// @param validBefore The authorisation is valid only before this time.
    /// @param nonce A unique id: the contract uses the position id, so each authorisation funds one position, once.
    /// @param signature `from`'s signature of the authorisation (EIP-712), or a contract wallet's.
    function receiveWithAuthorization(
        address from,
        address to,
        uint256 value,
        uint256 validAfter,
        uint256 validBefore,
        bytes32 nonce,
        bytes calldata signature
    )
        external;
}

