// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.38;

import {IManicFlashOptionErrors} from "../interfaces/IManicFlashOptionErrors.sol";
import {RepaySplit, SellSplit, SettleSplit} from "../types/MathTypes.sol";
import {Side, WithdrawPurpose} from "../types/StorageTypes.sol";

/// @title LeverageMath
/// @author Manic
/// @notice The Flash Option's maths: a position's liquidation and cap lines, its payout multiple, the fees, the
///         money splits of a settle, a sale and a repayment, and the checks on price times, the open gate, sales and
///         withdrawals. Every function is pure, and the backend computes the same numbers off-chain. docs/MATH.md
///         states each rule, with worked examples.
/// @dev Units:
///      - prices: `int64` at the market's price exponent (BTC: -8, so $83,884 is 8_388_400_000_000);
///      - amounts: `uint64` base units of the token (USDG has 6 decimals, so $10 is 10_000_000);
///      - the leverage L: a whole number from 1 to 10,000 (1000 is 1000x);
///      - payout multiples (g, floor, cap) and fee rates: basis points, where 10_000 is 1x or 100%;
///      - the liquidation distance θ: `thetaE7 = θ × 1e7`, so 2.627 bp is 2_627.
///      The maths runs in 256-bit integers, where none of these values can overflow, and each result is narrowed
///      once at the end with a range check that reverts `MathOverflow`. Every division rounds down (toward minus
///      infinity in `gBps`, whose dividend is negative on a losing move), which is always in the pool's favour.
///      The functions come in this order: `floorDiv`; the leverage checks (`leverageAllowed`, `thetaWithinLimit`,
///      `capReachable`); the lines and the payout (`lines`, `capLine`, `gBps`, `payout`, `maxProfit`, `touched`);
///      the time checks; the open gate; the fees; the settle split; the sale; the repay split; and the withdrawal
///      check.
/// @custom:security-contact See SECURITY.md
library LeverageMath {
    /// @notice The smallest allowed leverage L (1x). A leverage is a whole number: at L, every 1 bp the price moves
    ///         changes the payout by L/100 % of the stake (10% at 1000x, 5% at 500x, 1% at 100x).
    uint16 internal constant MIN_LEVERAGE = 1;

    /// @notice The largest allowed leverage L (10,000x).
    uint16 internal constant MAX_LEVERAGE = 10_000;

    /// @notice Basis points in 1x (or in 100%).
    uint256 internal constant BPS = 10_000;

    /// @notice The scale of θ: `thetaE7 = θ × 1e7`. A line θ away from entry is `entry × thetaE7 / 1e7` away.
    uint256 internal constant E7 = 10_000_000;

    /// @notice The highest payout cap a position may have, in bps of its stake (40_000 = 4x).
    uint16 internal constant MAX_LEVERAGE_CAP_BPS = 40_000;

    /// @notice The winner fee: 2% of the profit actually paid out (at settle, on a profitable sale, on each repayment).
    uint16 internal constant WINNER_FEE_BPS = 200;

    /// @notice The loser fee: 3% of a loss, taken while the pool's free money is at or above its floor.
    uint16 internal constant LOSER_FEE_BPS = 300;

    /// @notice The most seed recovery can ever take out of the pool, in whole tokens (× 10^decimals).
    uint64 internal constant SEED_RECOVERY_CAP_TOKENS = 500;

    /// @dev Signed copies for the signed maths in `lines` and `gBps`.
    // casting to int256 is safe because BPS (10_000) is far below type(int256).max
    // forge-lint: disable-next-line(unsafe-typecast)
    int256 private constant BPS_SIGNED = int256(BPS);
    // casting to int256 is safe because E7 (10_000_000) is far below type(int256).max
    // forge-lint: disable-next-line(unsafe-typecast)
    int256 private constant E7_SIGNED = int256(E7);

    /// @notice Divides `a` by `b`, rounding toward minus infinity.
    /// @dev Solidity's signed `/` rounds toward zero: `-7 / 2 == -3`, where the floor is -4. For a losing price move
    ///      that difference is money: rounding toward zero would round the loss in the user's favour. The callers
    ///      always divide by a positive price, so `type(int256).min / -1` (which reverts) can't occur.
    /// @param a The dividend.
    /// @param b The divisor; must not be 0 (division by zero panics).
    /// @return q The largest integer `q` with `q × b <= a` when `b > 0`.
    function floorDiv(int256 a, int256 b) internal pure returns (int256 q) {
        q = a / b;
        // A non-zero remainder with operands of opposite signs means `/` rounded up toward zero: step down by one.
        if (a % b != 0 && ((a < 0) != (b < 0))) q -= 1;
    }

    /// @notice Whether `leverage` is in the allowed range, `MIN_LEVERAGE` to `MAX_LEVERAGE` (1x to 10,000x).
    /// @param leverage The leverage L, a whole number (1000 is 1000x).
    /// @return True if the maths accepts it.
    function leverageAllowed(uint16 leverage) internal pure returns (bool) {
        return leverage >= MIN_LEVERAGE && leverage <= MAX_LEVERAGE;
    }

    /// @notice Whether a liquidation distance θ stays below 1/leverage, so the move to a position's line costs less
    ///         than its whole stake: `thetaE7 × leverage < 1e7`. That is under 10 bp at 1000x, 20 bp at 500x and
    ///         100 bp at 100x.
    /// @dev At the line the price has moved θ against the user, so the payout multiple is 1 − L × θ, which stays
    ///      above 0 only while L × θ < 1. The product is taken in 256 bits, where no `uint32` θ times a `uint16`
    ///      leverage can overflow.
    /// @param thetaE7 The liquidation distance θ × 1e7.
    /// @param leverage The leverage L.
    /// @return True if the line comes before a move that would take the whole stake.
    function thetaWithinLimit(uint32 thetaE7, uint16 leverage) internal pure returns (bool) {
        return uint256(thetaE7) * leverage < E7;
    }

    /// @notice Whether a short can reach the cap: `capBps − 10_000 < leverage × 10_000`, that is cap − 1x < L.
    /// @dev A short's payout grows by L × the fall in price, and a price can't fall below 0, so a short gains at most
    ///      L × its stake: a higher cap would put its cap line at or below 0. From 4x leverage up every cap up to the
    ///      4x ceiling passes, so the rule only binds at 1x, 2x and 3x. A cap below 1x counts as 1x (a gain of 0);
    ///      `lines` and the config check reject such a cap anyway.
    /// @param capBps The payout cap, in bps of the stake.
    /// @param leverage The leverage L.
    /// @return True if a short's cap line sits above 0.
    function capReachable(uint16 capBps, uint16 leverage) internal pure returns (bool) {
        uint256 capGainBps = capBps > BPS ? capBps - BPS : 0;
        return capGainBps < uint256(leverage) * BPS;
    }

    /// @notice The liquidation and cap prices of a position opened at `entry` with `leverage`.
    /// @dev The checks run in this order: the price, then the parameters.
    ///      - The liquidation line sits θ away from entry, whatever the leverage: `entry × thetaE7 / 1e7`. At
    ///        $83,884.00, θ = 2.627 bp puts it $22.04 away.
    ///      - The cap line is where the payout multiple reaches the cap: 1 + L × move = cap, so the move is
    ///        (cap − 1x) / L, which is `entry × (capBps − 10_000) / (L × 10_000)`. At 1000x a 4x cap is a
    ///        0.3% move ($251.65 from the same entry), at 500x a 2.5x cap is the same 0.3%, and at 100x a 2x cap is
    ///        1%.
    ///      Both offsets have positive operands, so truncating is flooring: each line sits at most one price unit
    ///      closer to entry. A long loses when the price falls, so its line is below entry and its cap above; a short
    ///      mirrors it.
    /// @param entry The entry price; must be positive (`InvalidPrice`).
    /// @param side `Call` (long) or `Put` (short).
    /// @param leverage The leverage L: `leverageAllowed` (`InvalidLeverageParams`).
    /// @param thetaE7 The liquidation distance θ × 1e7: positive, and `thetaWithinLimit` at L
    ///        (`InvalidLeverageParams`).
    /// @param capBps The payout cap: `10_000 < capBps <= MAX_LEVERAGE_CAP_BPS`, and `capReachable` at L
    ///        (`InvalidLeverageParams`).
    /// @return liqPrice Touching this price (equality counts) liquidates the position.
    /// @return capPrice The cap line, rounded toward the entry: the payout stops growing at this price, or one price
    ///         unit beyond it when the division isn't exact. `MathOverflow` if it doesn't fit `int64`.
    function lines(
        int64 entry,
        Side side,
        uint16 leverage,
        uint32 thetaE7,
        uint16 capBps
    )
        internal
        pure
        returns (int64 liqPrice, int64 capPrice)
    {
        if (entry <= 0) revert IManicFlashOptionErrors.InvalidPrice();
        if (
            !leverageAllowed(leverage) || thetaE7 == 0 || !thetaWithinLimit(thetaE7, leverage) || capBps <= BPS
                || capBps > MAX_LEVERAGE_CAP_BPS || !capReachable(capBps, leverage)
        ) revert IManicFlashOptionErrors.InvalidLeverageParams();
        int256 e = entry;
        int256 liqOffset = (e * int256(uint256(thetaE7))) / E7_SIGNED; // rounds down: the line moves toward entry
        // Rounds down too. L ≥ 1 here (checked above), so the divisor is at least 10_000.
        int256 capOffset = (e * (int256(uint256(capBps)) - BPS_SIGNED)) / (int256(uint256(leverage)) * BPS_SIGNED);
        if (side == Side.Call) {
            return (toInt64(e - liqOffset), toInt64(e + capOffset));
        }
        return (toInt64(e + liqOffset), toInt64(e - capOffset));
    }

    /// @notice The cap line of a position opened at `entry` with `leverage`: the price, rounded toward the entry,
    ///         where its payout stops growing (one price unit beyond it when the division isn't exact). The second line
    /// of `lines` on its own, for a position whose θ isn't stored (`getPosition`).
    /// @dev The same checks and the same arithmetic as `lines`' cap line, which doesn't use θ: the price, then the
    ///      leverage and the cap, then `entry ± entry × (capBps − 10_000) / (L × 10_000)`, rounded toward entry.
    ///      A fuzz test proves it equals `lines`' cap price for every entry, side, leverage and cap. Named for the
    ///      line, since `capPrice` is `lines`' return.
    /// @param entry The entry price; must be positive (`InvalidPrice`).
    /// @param side `Call` (the cap price is above entry) or `Put` (below).
    /// @param leverage The leverage L: `leverageAllowed` (`InvalidLeverageParams`).
    /// @param capBps The payout cap: `10_000 < capBps <= MAX_LEVERAGE_CAP_BPS`, and `capReachable` at L
    ///        (`InvalidLeverageParams`).
    /// @return The cap price. `MathOverflow` if it doesn't fit `int64`.
    function capLine(int64 entry, Side side, uint16 leverage, uint16 capBps) internal pure returns (int64) {
        if (entry <= 0) revert IManicFlashOptionErrors.InvalidPrice();
        if (
            !leverageAllowed(leverage) || capBps <= BPS || capBps > MAX_LEVERAGE_CAP_BPS
                || !capReachable(capBps, leverage)
        ) revert IManicFlashOptionErrors.InvalidLeverageParams();
        int256 e = entry;
        // Rounds down: toward entry. L ≥ 1 here (checked above), so the divisor is at least 10_000.
        int256 capOffset = (e * (int256(uint256(capBps)) - BPS_SIGNED)) / (int256(uint256(leverage)) * BPS_SIGNED);
        return toInt64(side == Side.Call ? e + capOffset : e - capOffset);
    }

    /// @notice The payout multiple g at `price`, in bps of the stake, for a position at `leverage` whose line was not
    ///         touched.
    /// @dev `R` is the move in the user's favour relative to entry, × L × 10_000, floored: L × the move in bps. At
    ///      1000x, +1 bp gives +1_000, so a +1 bp move pays 1.1x (11_000) and a -1 bp move 0.9x (9_000); at 100x, +1 bp
    ///      gives +100: 1.01x. g = 10_000 + R. Any winning move, however small (`R > 0`), pays at least the floor. g
    ///      never exceeds the cap and never goes below 0; only a move past the liquidation line could go that low, and
    ///      such a position is liquidated instead of settled. The prices are checked before the leverage.
    /// @param entry The entry price; must be positive (`InvalidPrice`).
    /// @param price The price to value the position at; must be positive (`InvalidPrice`).
    /// @param side `Call` (long) or `Put` (short).
    /// @param leverage The leverage L: `leverageAllowed` (`InvalidLeverageParams`).
    /// @param floorBps The least a winning position pays, in bps of its stake (e.g. 13_000 = 1.3x).
    /// @param capBps The most it pays, in bps of its stake (e.g. 40_000 = 4x).
    /// @return The payout multiple in bps, between 0 and `capBps`.
    function gBps(
        int64 entry,
        int64 price,
        Side side,
        uint16 leverage,
        uint16 floorBps,
        uint16 capBps
    )
        internal
        pure
        returns (uint16)
    {
        if (entry <= 0 || price <= 0) revert IManicFlashOptionErrors.InvalidPrice();
        if (!leverageAllowed(leverage)) revert IManicFlashOptionErrors.InvalidLeverageParams();
        // The price move in the user's favour: positive for both sides when the position is winning.
        int256 favourableMove = side == Side.Call ? int256(price) - entry : int256(entry) - price;
        // Floored, so a losing move never rounds in the user's favour (-$8 on $83,884 at 1000x pays 9_046, not
        // 9_047). The product fits easily: a move below 2^64 times L × 10_000 below 2^27.
        int256 r = floorDiv(favourableMove * (int256(uint256(leverage)) * BPS_SIGNED), entry);
        int256 g = BPS_SIGNED + r;
        int256 floor = int256(uint256(floorBps));
        int256 cap = int256(uint256(capBps));
        if (r > 0 && g < floor) g = floor;
        if (g > cap) g = cap;
        if (g < 0) g = 0;
        return toUint16(g);
    }

    /// @notice What a position pays at multiple `multipleBps`: `stake × multipleBps / 10_000`.
    /// @param stake The position's stake, in token base units.
    /// @param multipleBps The payout multiple, in bps (from `gBps`).
    /// @return The payout, rounded down (pool favoured). `MathOverflow` if it doesn't fit `uint64`.
    function payout(uint64 stake, uint16 multipleBps) internal pure returns (uint64) {
        return toUint64((uint256(stake) * multipleBps) / BPS); // rounds down: pool favoured
    }

    /// @notice The most a position can win above its stake: `stake × (capBps − 10_000) / 10_000`. Opening a position
    ///         adds it to the pool's open exposure, and ending it subtracts the same value.
    /// @param stake The position's stake, in token base units.
    /// @param capBps The position's payout cap; must be at least 10_000 (`InvalidLeverageParams`). Note the bound is
    ///        `>=` here but `>` in `lines`: a 1x cap has a max profit of 0.
    /// @return The max profit, rounded down. `MathOverflow` if it doesn't fit `uint64`.
    function maxProfit(uint64 stake, uint16 capBps) internal pure returns (uint64) {
        if (capBps < BPS) revert IManicFlashOptionErrors.InvalidLeverageParams();
        return toUint64((uint256(stake) * (capBps - BPS)) / BPS); // rounds down: pool favoured
    }

    /// @notice Whether `price` touches the liquidation line. Equality counts.
    /// @param price The price to check.
    /// @param liqPrice The position's liquidation line.
    /// @param side `Call`: touched at or below the line. `Put`: touched at or above it.
    /// @return True if the position is liquidated at `price`.
    function touched(int64 price, int64 liqPrice, Side side) internal pure returns (bool) {
        return side == Side.Call ? price <= liqPrice : price >= liqPrice;
    }

    /// @notice Checks that a price tick liquidates a position.
    /// @dev The checks run in this order: a positive price; the tick inside the position's life, both ends included;
    ///      the tick no further ahead of the chain's clock than the skew; and the price touching the line (equality
    ///      counts). Old ticks are accepted, so the backend can replay after an outage. The price and the tick time
    ///      are the same for a whole batch, so their errors carry no id; the two that depend on the position do.
    ///      The comparisons never add or subtract past zero, so they can't overflow.
    /// @param positionId The position being liquidated, named in its errors.
    /// @param startTime The position's entry tick time.
    /// @param endTime The position's expiry time.
    /// @param liqPrice The position's liquidation line.
    /// @param side `Call` (liquidated at or below the line) or `Put` (at or above).
    /// @param price The tick's price; must be positive (`InvalidPrice`).
    /// @param publishTime The tick's time: `startTime <= publishTime <= endTime` (`InvalidLiquidationWindow`).
    /// @param currentTime The chain's clock (`block.timestamp`).
    /// @param clockSkewSecs How far ahead of the clock a tick may be (`PriceFromFuture`).
    function checkLiquidation(
        bytes32 positionId,
        uint256 startTime,
        uint256 endTime,
        int64 liqPrice,
        Side side,
        int64 price,
        uint256 publishTime,
        uint256 currentTime,
        uint8 clockSkewSecs
    )
        internal
        pure
    {
        if (price <= 0) revert IManicFlashOptionErrors.InvalidPrice();
        if (publishTime < startTime || publishTime > endTime) {
            revert IManicFlashOptionErrors.InvalidLiquidationWindow(positionId);
        }
        if (isFromTheFuture(publishTime, currentTime, clockSkewSecs)) revert IManicFlashOptionErrors.PriceFromFuture();
        if (!touched(price, liqPrice, side)) revert IManicFlashOptionErrors.LiquidationPriceNotReached(positionId);
    }

    /// @notice Checks the time of the price tick an open or a sale uses.
    /// @dev The checks run in this order: a tick time at all (0 is `PriceTooOld`); no further ahead of the clock than
    ///      the skew; no older than the maximum age. A tick a little ahead of the clock counts as age 0.
    /// @param currentTime The chain's clock (`block.timestamp`), used only as a sanity bound.
    /// @param publishTime The tick's time.
    /// @param maxAgeSecs The oldest a tick may be, in seconds (`PriceTooOld`).
    /// @param clockSkewSecs How far ahead of the clock a tick may be (`PriceFromFuture`).
    function checkEntryTime(
        uint256 currentTime,
        uint256 publishTime,
        uint8 maxAgeSecs,
        uint8 clockSkewSecs
    )
        internal
        pure
    {
        if (publishTime == 0) revert IManicFlashOptionErrors.PriceTooOld();
        if (isFromTheFuture(publishTime, currentTime, clockSkewSecs)) revert IManicFlashOptionErrors.PriceFromFuture();
        if (currentTime > publishTime && currentTime - publishTime > maxAgeSecs) {
            revert IManicFlashOptionErrors.PriceTooOld();
        }
    }

    /// @notice The open gate.
    /// @dev A new position is rejected while the total owed exceeds `maxTotalOwed`, and, when `maxExposureBps > 0`,
    ///      when the open positions' max profit plus this one's would exceed `free × maxExposureBps / 10_000`. The
    ///      limit rounds down, so the gate errs on the pool's side. At launch `maxExposureBps` is 10_000: the open
    ///      max profit can never exceed free money, so every winner can be paid in full. 0 turns the gate off here,
    ///      but `ConfigLib.validate` keeps a market's value at 1 to 10_000 (ADR 0009).
    /// @param totalOwed The pool's total owed to winners.
    /// @param maxTotalOwed The market's limit on it (`OpenBlockedTotalOwed`).
    /// @param openMaxProfit The sum of the open positions' max profit.
    /// @param newMaxProfit The new position's max profit.
    /// @param free The pool's free money (`total - lockedMargin`).
    /// @param maxExposureBps The exposure limit in bps of free money; 0 turns it off (`OpenBlockedExposure`).
    function openGate(
        uint64 totalOwed,
        uint64 maxTotalOwed,
        uint64 openMaxProfit,
        uint64 newMaxProfit,
        uint64 free,
        uint32 maxExposureBps
    )
        internal
        pure
    {
        if (totalOwed > maxTotalOwed) revert IManicFlashOptionErrors.OpenBlockedTotalOwed();
        if (maxExposureBps > 0) {
            uint256 exposure = uint256(openMaxProfit) + newMaxProfit;
            uint256 limit = (uint256(free) * maxExposureBps) / BPS; // rounds down: pool favoured
            if (exposure > limit) revert IManicFlashOptionErrors.OpenBlockedExposure();
        }
    }

    /// @notice `amount × feeBps / 10_000`.
    /// @dev Rounds down, so a fee never rounds against the user, and the rate is clamped to 100%, so a fee never
    ///      exceeds `amount`.
    /// @param amount The amount the fee is taken from.
    /// @param feeBps The fee rate in bps (values above 10_000 count as 10_000).
    /// @return The fee.
    function fee(uint64 amount, uint16 feeBps) internal pure returns (uint64) {
        uint256 rate = feeBps < BPS ? feeBps : BPS;
        return toUint64((uint256(amount) * rate) / BPS); // rounds down: user favoured; at most `amount`
    }

    /// @notice The 2% winner fee on profit actually paid to the user.
    /// @dev Taken at settle, on a profitable sale and on each repayment. Profit that is only owed pays no fee until it
    ///      is repaid.
    /// @param profitPaid The profit paid out now.
    /// @return The winner fee.
    function winnerFee(uint64 profitPaid) internal pure returns (uint64) {
        return fee(profitPaid, WINNER_FEE_BPS);
    }

    /// @notice The 3% loser fee on `loss`, taken only while the pool's free money is at or above its floor.
    /// @dev `freeBefore` is the free money before this order. A queue only forms once free money has run out, and
    ///      repayments spend new losers' money on it, so the fee is usually skipped while winners are owed.
    /// @param loss The loss (the whole stake when liquidated).
    /// @param freeBefore The pool's free money before this order.
    /// @param poolFloor The pool's floor.
    /// @return The loser fee, or 0 below the floor.
    function loserFee(uint64 loss, uint64 freeBefore, uint64 poolFloor) internal pure returns (uint64) {
        return freeBefore >= poolFloor ? fee(loss, LOSER_FEE_BPS) : 0;
    }

    /// @notice Splits an expiry payout into the user's own stake, profit paid now, profit owed, and the fees.
    /// @dev The user's own stake comes back first: all of it on a win, what is left of it on a loss. Anything above
    ///      the stake is profit, which only free money can pay. While anyone is owed (`totalOwed > 0`), a new
    ///      winner's whole profit joins the queue, so nobody jumps it.
    /// @param payoutAmount What the position pays at expiry (`payout(stake, gBps(...))`).
    /// @param stake The position's stake.
    /// @param freeBefore The pool's free money with this position's stake still held.
    /// @param totalOwed The pool's total owed before this settle.
    /// @param poolFloor The pool's floor, for the loser fee.
    /// @return split The split. See `SettleSplit`.
    function settleSplit(
        uint64 payoutAmount,
        uint64 stake,
        uint64 freeBefore,
        uint64 totalOwed,
        uint64 poolFloor
    )
        internal
        pure
        returns (SettleSplit memory split)
    {
        split.own = payoutAmount < stake ? payoutAmount : stake;
        uint64 profit = payoutAmount - split.own;
        if (totalOwed == 0) split.paid = profit < freeBefore ? profit : freeBefore;
        split.owed = profit - split.paid;
        split.winnerFee = winnerFee(split.paid);
        split.loserFee = loserFee(stake - split.own, freeBefore, poolFloor);
    }

    /// @notice What the user receives now from a settle: `own + paid - winnerFee`.
    /// @param split A settle split.
    /// @return The amount for the user.
    function toUser(SettleSplit memory split) internal pure returns (uint64) {
        return split.own + split.paid - split.winnerFee;
    }

    /// @notice What leaves the pool's books on a settle: the user's part and both fees, `own + paid + loserFee`.
    /// @param split A settle split.
    /// @return The amount that leaves the pool's `total`.
    function outOfPool(SettleSplit memory split) internal pure returns (uint64) {
        return split.own + split.paid + split.loserFee;
    }

    /// @notice Checks that a sale's tick falls inside the position's sell window: at least `minDelaySecs` after the
    ///         start, and more than `cutoffSecs` before the end.
    /// @dev Written as comparisons that can't overflow: a tick before the start is too early, and an end at or below
    ///      the cutoff closes the window, so neither subtraction goes below zero.
    /// @param startTime The position's entry tick time.
    /// @param endTime The position's expiry time.
    /// @param publishTime The sale's tick time.
    /// @param minDelaySecs How long after the start a sale is first allowed.
    /// @param cutoffSecs How long before the end sales stop (`SellWindowClosed` for every bound).
    function checkSellWindow(
        uint256 startTime,
        uint256 endTime,
        uint256 publishTime,
        uint16 minDelaySecs,
        uint16 cutoffSecs
    )
        internal
        pure
    {
        bool tooEarly = publishTime < startTime || publishTime - startTime < minDelaySecs;
        bool tooLate = endTime <= cutoffSecs || publishTime >= endTime - cutoffSecs;
        if (tooEarly || tooLate) revert IManicFlashOptionErrors.SellWindowClosed();
    }

    /// @notice Checks the amounts of an early sale.
    /// @dev The checks run in this order: the valuation against what the position pays at this price; the sale
    ///      amount against the valuation; the early-sell fee (`valuation - sellAmount`) against its cap; the user's
    ///      minimum; and that the pool can pay the sale in full right now: nobody owed, and the valuation within free
    ///      money plus the position's own stake. A sale is never partly paid.
    /// @param stake The position's stake.
    /// @param gNowBps The position's payout multiple at the sale price.
    /// @param valuation What the backend values the position at (`ValuationAboveCurrentPayout`).
    /// @param sellAmount What the user gets before the winner fee (`SellAmountExceedsValuation`, `SellFeeTooHigh`).
    /// @param minAmount The least the user signed for (`SellAmountBelowMin`).
    /// @param maxSellFeeBps The market's early-sell fee cap, in bps of the valuation.
    /// @param totalOwed The pool's total owed (`QueueNotEmpty`).
    /// @param freeBefore The pool's free money with this position's stake still held (`SellNotPayable`).
    function checkSell(
        uint64 stake,
        uint16 gNowBps,
        uint64 valuation,
        uint64 sellAmount,
        uint64 minAmount,
        uint16 maxSellFeeBps,
        uint64 totalOwed,
        uint64 freeBefore
    )
        internal
        pure
    {
        if (valuation > payout(stake, gNowBps)) revert IManicFlashOptionErrors.ValuationAboveCurrentPayout();
        if (sellAmount > valuation) revert IManicFlashOptionErrors.SellAmountExceedsValuation();
        if (valuation - sellAmount > fee(valuation, maxSellFeeBps)) revert IManicFlashOptionErrors.SellFeeTooHigh();
        if (sellAmount < minAmount) revert IManicFlashOptionErrors.SellAmountBelowMin();
        if (totalOwed != 0) revert IManicFlashOptionErrors.QueueNotEmpty();
        if (uint256(valuation) > uint256(freeBefore) + stake) revert IManicFlashOptionErrors.SellNotPayable();
    }

    /// @notice Splits a sale that `checkSell` accepted.
    /// @dev The winner fee is 2% of the profit the user takes (`sellAmount - stake`, if positive). The loser fee is 3%
    ///      of the loss in the valuation (`stake - valuation`, if positive), measured against the floor with
    ///      `freeBefore`, as at settle. Requires `sellAmount <= valuation`, which `checkSell` guarantees.
    /// @param stake The position's stake.
    /// @param valuation The accepted valuation.
    /// @param sellAmount The accepted sale amount.
    /// @param freeBefore The pool's free money with this position's stake still held.
    /// @param poolFloor The pool's floor, for the loser fee.
    /// @return split The split. See `SellSplit`.
    function sellSplit(
        uint64 stake,
        uint64 valuation,
        uint64 sellAmount,
        uint64 freeBefore,
        uint64 poolFloor
    )
        internal
        pure
        returns (SellSplit memory split)
    {
        split.winnerFee = winnerFee(sellAmount > stake ? sellAmount - stake : 0);
        split.toUser = sellAmount - split.winnerFee;
        split.sellFee = valuation - sellAmount;
        split.loserFee = loserFee(stake > valuation ? stake - valuation : 0, freeBefore, poolFloor);
    }

    /// @notice What goes to the fee recipient on a sale: the early-sell fee and the winner or loser fee.
    /// @param split A sell split.
    /// @return The total fees.
    function fees(SellSplit memory split) internal pure returns (uint64) {
        return split.sellFee + split.winnerFee + split.loserFee;
    }

    /// @notice What leaves the pool's books on a sale: `toUser + fees`, which equals the valuation plus the loser fee.
    /// @param split A sell split.
    /// @return The amount that leaves the pool's `total`.
    function outOfPool(SellSplit memory split) internal pure returns (uint64) {
        return split.toUser + fees(split);
    }

    /// @notice Repays an IOU of `owed` from free money (never from open stakes), as much as free money allows, with
    ///         the 2% winner fee on each repayment.
    /// @param owed What the IOU still owes.
    /// @param free The pool's free money.
    /// @return split The split. See `RepaySplit`.
    function repaySplit(uint64 owed, uint64 free) internal pure returns (RepaySplit memory split) {
        split.amount = owed < free ? owed : free;
        split.winnerFee = winnerFee(split.amount);
        split.toUser = split.amount - split.winnerFee;
        split.remaining = owed - split.amount;
    }

    /// @notice Checks an admin withdrawal from the pool.
    /// @dev The checks run in this order: a positive amount; nobody owed; free money staying at or above the floor,
    ///      which also rejects an amount above free money; what is left above the floor still covering every open
    ///      position's max profit, so a withdrawal never leaves open bets unpayable (docs/ARCHITECTURE.md §8.1);
    ///      and, for seed recovery, at most 500 whole tokens in total.
    /// @param purpose Seed recovery (capped) or rewards (not capped).
    /// @param amount The amount to withdraw (`InvalidAmount` if 0).
    /// @param free The pool's free money (`total - lockedMargin`), so open stakes can never be withdrawn.
    /// @param totalOwed The pool's total owed (`OwedOutstanding`).
    /// @param poolFloor The pool's floor (`BelowPoolFloor`).
    /// @param openMaxProfit The sum of the open positions' max profit (`OpenExposureNotCovered`).
    /// @param seedRecovered The seed recovered so far (`SeedRecoveryExceeded`).
    /// @param decimals The token's decimals, which scale the 500-token cap (`MathOverflow` if it can't fit).
    function checkWithdraw(
        WithdrawPurpose purpose,
        uint64 amount,
        uint64 free,
        uint64 totalOwed,
        uint64 poolFloor,
        uint64 openMaxProfit,
        uint64 seedRecovered,
        uint8 decimals
    )
        internal
        pure
    {
        if (amount == 0) revert IManicFlashOptionErrors.InvalidAmount();
        if (totalOwed != 0) revert IManicFlashOptionErrors.OwedOutstanding();
        if (uint256(free) < uint256(amount) + poolFloor) revert IManicFlashOptionErrors.BelowPoolFloor();
        if (uint256(free) - amount - poolFloor < openMaxProfit) {
            revert IManicFlashOptionErrors.OpenExposureNotCovered();
        }
        if (purpose == WithdrawPurpose.SeedRecovery) {
            uint64 cap = wholeTokens(SEED_RECOVERY_CAP_TOKENS, decimals);
            if (uint256(seedRecovered) + amount > cap) revert IManicFlashOptionErrors.SeedRecoveryExceeded();
        }
    }

    /// @dev `tokens` whole tokens in base units (`tokens × 10^decimals`), reverting `MathOverflow` when `10^decimals`
    ///      or the product doesn't fit `uint64`. `10^20` already exceeds `uint64`, so larger decimals stop early,
    ///      before `10**decimals` could overflow even 256 bits.
    function wholeTokens(uint64 tokens, uint8 decimals) private pure returns (uint64) {
        if (decimals > 19) revert IManicFlashOptionErrors.MathOverflow();
        return toUint64(uint256(tokens) * 10 ** uint256(decimals));
    }

    /// @dev True if `publishTime` is ahead of `currentTime` by more than `clockSkewSecs`, written without adding so
    ///      it can't overflow.
    function isFromTheFuture(uint256 publishTime, uint256 currentTime, uint8 clockSkewSecs)
        private
        pure
        returns (bool)
    {
        return publishTime > currentTime && publishTime - currentTime > clockSkewSecs;
    }

    /// @dev Narrows to `int64`, reverting `MathOverflow` instead of truncating.
    function toInt64(int256 value) private pure returns (int64) {
        if (value < type(int64).min || value > type(int64).max) revert IManicFlashOptionErrors.MathOverflow();
        // forge-lint: disable-next-line(unsafe-typecast)
        return int64(value); // in range: checked on the line above
    }

    /// @dev Narrows to `uint64`, reverting `MathOverflow` instead of truncating.
    function toUint64(uint256 value) private pure returns (uint64) {
        if (value > type(uint64).max) revert IManicFlashOptionErrors.MathOverflow();
        // forge-lint: disable-next-line(unsafe-typecast)
        return uint64(value); // in range: checked on the line above
    }

    /// @dev Narrows a clamped multiple to `uint16`, reverting `MathOverflow` instead of truncating. After `gBps`
    ///      clamps g to `[0, capBps]` this can't fail; the check keeps the cast honest.
    function toUint16(int256 value) private pure returns (uint16) {
        if (value < 0 || value > int256(uint256(type(uint16).max))) revert IManicFlashOptionErrors.MathOverflow();
        // forge-lint: disable-next-line(unsafe-typecast)
        return uint16(uint256(value)); // in range: checked on the line above
    }
}

